\title{Homotopy Type Theory Foundations: Identity Types, Higher Inductive
Types, and the Boundary of Univalence in a Proof-Irrelevant Setting}
\author{Aristotle}
\date{June 24, 2026}

\begin{document}

\begin{abstract}
We develop core fragments of Homotopy Type Theory (HoTT)---identity types,
higher inductive types, and univalence---inside a dependently typed proof system
whose built-in propositional equality is \emph{proof-irrelevant}, i.e.\ whose
identity types are subsingletons. Three results anchor the development. First, we
prove the \textbf{fundamental theorem of identity types}: for a pointed family
$B$ over $(A,a)$ with $b : B(a)$, the canonical transport map
$\encode_x : (a = x) \to B(x)$ is a fiberwise equivalence (contractible-fibers
sense) \emph{iff} the total space $\sum_x B(x)$ is contractible. Second, we
realize the simplest \textbf{higher inductive type}, the propositional truncation
$\Trunc{A}$, as a quotient by the total relation, prove it is a mere proposition
(the path constructor), establish its recursion and dependent induction
principles, prove idempotence on propositions, and prove that it commutes with
binary products, $\Trunc{A \times B} \simeq \Trunc{A} \times \Trunc{B}$. Third,
we analyze the \textbf{univalence axiom}: we show bundled univalence data is
\emph{inconsistent} (a contradiction is derivable from the two distinct
self-equivalences of $\Bool$), while univalence \emph{nevertheless holds} on the
universe of propositions, realized by $\idToEquiv$ and underwritten by
propositional extensionality. The unifying theme is that a proof-irrelevant
system behaves as the \emph{$0$-truncated shadow} of a univalent universe. All
results are formalized and machine-checked.
\end{abstract}

\maketitle

\section{Introduction}

Homotopy Type Theory interprets the identity type $a = b$ of Martin-L\"of type
theory as a \emph{path space}: a type whose elements are identifications of $a$
with $b$, and whose own identity types encode higher identifications. Under this
reading, types are $\infty$-groupoids, functions are functors, and logical
constructions acquire geometric meaning. Three ingredients give the theory its
shape: the \emph{fundamental theorem of identity types}, \emph{higher inductive
types} (HITs), and the \emph{univalence axiom}.

This paper formalizes representative results for each, and records what changes
when the ambient equality is \emph{proof-irrelevant}---when each identity type
$a = x$ is a subsingleton. We call this the \textbf{$0$-truncated shadow} of
HoTT. Our central finding is a trichotomy: statements invariant under
$0$-truncation become short (the fundamental theorem); the
propositional-truncation HIT is fully realizable, its higher content isolated in
a single lemma; and univalence becomes globally inconsistent yet survives on
propositions.

\subsection{Conventions}
We use $\mathrm{Sort}$-polymorphic definitions so identity-type domains
(living in $\mathrm{Prop} = \mathrm{Sort}\,0$) are admissible. Dependent pairs
are written $\sum' x,\, B\,x$ (the \texttt{PSigma} total space). Transport of
$u : B(a)$ along $p : a = x$ is written $p_*(u)$.

\section{Identity types and the fundamental theorem}

\begin{definition}[Contractibility]
A type $A$ is \emph{contractible}, $\IsContr(A)$, if equipped with a
\emph{center} $c : A$ and a \emph{contraction} $\prod_{x:A}(c = x)$. Contractible
types are the $(-2)$-truncated types.
\end{definition}

\begin{definition}[Fiber]
For $f : A \to B$ and $y : B$, the homotopy fiber is
$\Fiber(f, y) := \sum' x : A,\; f(x) = y$.
\end{definition}

\begin{definition}[Equivalence]
$f : A \to B$ is an \emph{equivalence}, $\IsEquiv(f)$, if every fiber is
contractible: $\prod_{y:B}\IsContr(\Fiber(f,y))$.
\end{definition}

\begin{lemma}[Contractible $\Rightarrow$ subsingleton]\label{lem:sub}
If $\IsContr(A)$ then $\prod_{x,y:A}(x = y)$.
\end{lemma}
\begin{proof}
Rewrite $x$ and $y$ along the contraction at the center: $x = c = y$.
\end{proof}

\begin{theorem}[Based path spaces are contractible]\label{thm:singleton}
For any $a : A$, the type $\sum' y : A,\; a = y$ is contractible, with center
$(a, \refl)$.
\end{theorem}
\begin{proof}
The center is $(a,\refl)$. For the contraction, take $(y,p)$ and path-induct on
$p$; the sole case $p = \refl$, $y = a$ gives the goal by reflexivity.
\end{proof}

\begin{definition}[Encode / transport]
For $B : A \to \mathrm{Sort}$, $a : A$, $b : B(a)$, define
$\encode_x : (a = x) \to B(x)$, $\encode_x(p) := p_*(b)$.
\end{definition}

\begin{theorem}[Fundamental Theorem of Identity Types]\label{thm:ftit}
Let $B : A \to \mathrm{Sort}$, $a : A$, $b : B(a)$. Then
\[
\Big(\textstyle\prod_{x:A}\IsEquiv(\encode_x)\Big)
\;\Longleftrightarrow\;
\IsContr\Big(\textstyle\sum' x : A,\; B(x)\Big).
\]
\end{theorem}
\begin{proof}[Proof sketch]
\emph{(Forward.)} Assume each $\encode_x$ is an equivalence. Propose $(a,b)$ as
center. For $(x,u)$, the fiber over $u$ is inhabited: there is $p : a = x$ with
$p_*(b) = u$. Path-induct on $p$; the witness collapses $u$ to $b$, so
$(x,u)=(a,b)$. Only inhabitedness (surjectivity) of fibers is used.

\emph{(Backward.)} Assume the total space contractible; by
Lemma~\ref{lem:sub} it is a subsingleton. Fix $x$, $u : B(x)$. Subsingleton-ness
gives $(a,b)=(x,u)$; projecting yields $a = x$ and (after substitution) an
identification of $b$ with $u$, producing an element of the fiber. The fiber is a
$\texttt{PSigma}$ of two proof-irrelevant components, hence any two elements are
equal and the exhibited one is a center.
\end{proof}

\begin{remark}
In a proof-irrelevant ambient system, each direction reduces to inhabitedness of
fibers plus subsingleton-ness; no transport-coherence bookkeeping is needed. This
is the set-level shadow of the fundamental theorem.
\end{remark}

\begin{corollary}\label{cor:lift}
For the lifted identity family $x \mapsto \mathrm{PLift}(a = x)$ with base point
$\langle\refl\rangle$, the map $\encode_x$ is a fiberwise equivalence.
\end{corollary}
\begin{proof}
Apply Theorem~\ref{thm:ftit} (backward); its hypothesis follows from
Theorem~\ref{thm:singleton}.
\end{proof}

\section{Higher inductive types: propositional truncation}

\begin{definition}[Propositional truncation]
For $A : \mathrm{Sort}\,u$, define $\Trunc{A} := \mathrm{Quot}(\lambda\,\_\,\_.\ \top)$,
the quotient of $A$ by the total relation, with point constructor
$\mk : A \to \Trunc{A}$. The path constructor is derived from totality via
$\mathrm{Quot.sound}$ on $\mathrm{trivial} : \top$.
\end{definition}

\begin{theorem}[$\Trunc{A}$ is a mere proposition]\label{thm:isprop}
For all $x, y : \Trunc{A}$, $x = y$.
\end{theorem}
\begin{proof}[Proof sketch]
By $\mathrm{Quot.ind}$ reduce $x,y$ to $\mk(a),\mk(b)$; then
$\mathrm{Quot.sound}$ on $\mathrm{trivial}$ gives $\mk(a)=\mk(b)$.
\end{proof}

\begin{theorem}[Recursion and induction]\label{thm:univ}
Let $P$ be a proposition. \emph{(i)} For $f : A \to P$ there is
$\mathrm{lift}\,f : \Trunc{A} \to P$ with
$\mathrm{lift}\,f(\mk\,a) = f\,a$. \emph{(ii)} For a family of propositions
$P : \Trunc{A} \to \mathrm{Prop}$, to prove $\prod_t P(t)$ it suffices to prove
$\prod_a P(\mk\,a)$.
\end{theorem}
\begin{proof}[Proof sketch]
For (i), $f$ respects the total relation because $P$ is a subsingleton
($f\,a = f\,b$ by $\mathrm{Subsingleton.elim}$); $\mathrm{Quot.lift}$ applies and
the computation rule holds definitionally. (ii) follows from $\mathrm{Quot.ind}$
and subsingleton-ness of each $P(t)$.
\end{proof}

\begin{theorem}[Idempotence on propositions]\label{thm:idem}
If $A$ is a proposition, $\mk : A \to \Trunc{A}$ is an equivalence; equivalently
$\Trunc{A} \simeq A$.
\end{theorem}
\begin{proof}[Proof sketch]
The inverse is $\mathrm{lift}(\mathrm{id}_A)$, valid since $A$ is a proposition.
Round-trips hold by the computation rule and by Theorem~\ref{thm:isprop}.
\end{proof}

\begin{theorem}[Truncation preserves binary products]\label{thm:prod}
$\Trunc{A \times B} \simeq \Trunc{A} \times \Trunc{B}$.
\end{theorem}
\begin{proof}[Proof sketch]
Forward: lift $(a,b) \mapsto (\mk\,a, \mk\,b)$ (the target is a product of
propositions, hence a proposition). Backward: given $(s,t)$, eliminate $s$ then
$t$ through the truncation (nested lifts), recovering $a,b$ and returning
$\mk(a,b)$; well defined since $\Trunc{A\times B}$ is a proposition. The
composites agree by Theorem~\ref{thm:isprop}.
\end{proof}

\section{Univalence: global failure and propositional survival}

\begin{definition}[$\idToEquiv$ and univalence data]
For types $A,B$ there is a canonical map $\idToEquiv : (A = B) \to (A \simeq B)$
sending $\refl$ to the identity equivalence. \emph{Univalence data} bundles
$\idToEquiv$ with the data witnessing it is an equivalence (an inverse with
round-trip laws).
\end{definition}

\begin{definition}[The Bool obstruction]
Let $\negEquiv : \Bool \simeq \Bool$ be the equivalence given by Boolean
negation. It differs from the identity equivalence, since they disagree on
$\mathrm{true}$.
\end{definition}

\begin{theorem}[Univalence is inconsistent in the proof-irrelevant setting]\label{thm:univ-bad}
From univalence data one derives $\bot$.
\end{theorem}
\begin{proof}[Proof sketch]
Let $g$ invert $\idToEquiv$. Apply $g$ to the distinct self-equivalences
$\mathrm{refl}_\simeq$ and $\negEquiv$ of $\Bool$, getting two identifications
$\Bool = \Bool$. By proof-irrelevance these are equal; applying $\idToEquiv$ and
the section law for $g$ yields $\mathrm{refl}_\simeq = \negEquiv$, a
contradiction.
\end{proof}

\begin{remark}
The contradiction is powered by a non-subsingleton equivalence type:
$\lvert \Bool \simeq \Bool\rvert = 2$ while $\lvert \Bool = \Bool\rvert = 1$.
Univalence demands proof-relevance; $\Bool$ is the minimal witness against it.
\end{remark}

\begin{theorem}[Univalence on propositions]\label{thm:univ-good}
For propositions $P, Q$, $(P = Q) \simeq (P \simeq Q)$, realized by $\idToEquiv$.
\end{theorem}
\begin{proof}[Proof sketch]
For propositions, an equivalence $P \simeq Q$ is the data of a logical
equivalence $P \leftrightarrow Q$ (round-trips automatic by subsingleton-ness).
Propositional extensionality turns $P \leftrightarrow Q$ into $P = Q$, inverting
$\idToEquiv$. Round-trip laws hold because $P = Q$ is a subsingleton.
\end{proof}

\begin{remark}
The obstruction vanishes because a proposition has no nontrivial
self-equivalence ($\lvert P \simeq P\rvert \le 1$). The propositional fragment is
the largest sub-universe on which $\idToEquiv$ is an equivalence in a
proof-irrelevant foundation.
\end{remark}

\section{Algorithms}

\begin{description}
\item[Algorithm A: Fiberwise-equivalence $\Leftrightarrow$ contractible-total-space
checker.] Over a finite base $A$ and finite family $B$, build each fiber of
$\encode_x$ and test contractibility (exactly one element), test contractibility
of $\sum_x B(x)$, and verify the verdicts agree---a finite instance of
Theorem~\ref{thm:ftit}. Complexity $O\big(\sum_x \lvert a=x\rvert\cdot\lvert B(x)\rvert\big)$.
\item[Algorithm B: Propositional-truncation product oracle.] For finite $A,B$,
compute inhabitation of $A \times B$ and of $A,B$ and verify
Theorem~\ref{thm:prod}: $A\times B$ inhabited iff both $A$ and $B$ are.
\item[Algorithm C: Univalence-obstruction detector.] For finite $T$, enumerate
$\Aut(T)$ and compare $\lvert\Aut(T)\rvert$ with the number of self-identifications
in a proof-irrelevant identity type ($1$). The obstruction of
Theorem~\ref{thm:univ-bad} is present iff $\lvert\Aut(T)\rvert > 1$; the minimal
witness is $\Bool$ with $\lvert\Aut(\Bool)\rvert = 2$.
\end{description}

\section{Discussion}

A proof-irrelevant foundation is the $0$-truncated shadow of a univalent
universe: every identity type is a subsingleton. Consequently, a HoTT theorem
invariant under $0$-truncation becomes short (the fundamental theorem); a HIT
whose universal property targets propositions is fully realizable, its higher
content concentrated in one lemma (here $\mathrm{isProp}$); and a principle
requiring proof-relevance (univalence) fails globally but persists exactly on the
propositional part of the universe.

\section{Future work}
We conjecture: (1) truncation level controls which HoTT theorems collapse, via
finer quotient encodings of $n$-truncation; (2) the Bool obstruction is the
unique minimal witness of non-univalence, formalizable through
$\lvert\Aut(T)\rvert$; (3) propositional univalence extends to a reflective
subuniverse of $h$-propositions that is the largest sub-universe satisfying
univalence.

\end{document}

